קכט. עִקַּר תַּאֲוַת מָמוֹן שֶׁמְּבַלֶּה יְמֵי הָאָדָם, הַכֹּל הוּא עַל־יְדֵי פְּגַם הַלְּבוּשִׁין, כִּי בֶּאֱמֶת מְלֻבָּשׁ בְּהַמָּמוֹן גַּוְנִין עִלָּאִין מְאֹד, אַךְ שֶׁנֶּעְלָם וְנִתְכַּסֶּה וְנִתְלַבֵּשׁ מְאֹד. וּמִי שֶׁזּוֹכֶה לְהַאֲמִין וּלְהִסְתַּכֵּל עַל הַפְּנִימִיּוּת שֶׁמְּלֻבָּשׁ בְּהַמָּמוֹן, שֶׁהֵם הַגַּוְנִין עִלָּאִין הַנַּ"ל, בְּוַדַּאי לֹא יִתְאַוֶּה לַמָּמוֹן הַגַּשְׁמִי כְּלָל, וּמִכָּל־שֶׁכֵּן שֶׁלֹּא הָיָה נוֹגֵעַ בְּמָמוֹן חֲבֵרוֹ, חַס וְשָׁלוֹם. רַק אִם אֵינוֹ מִסְתַּכֵּל רַק עַל חִיצוֹנִיּוּת הַמָּמוֹן, בְּוַדַּאי אֶפְשָׁר לְהִלָּכֵד בָּזֶה מְאֹד, עַד שֶׁיָּבוֹא לִידֵי הַכְחָשׁוֹת וּגְזֵלוֹת גְּמוּרוֹת, חַס וְשָׁלוֹם. וְכֵן בְּכָל הָעֲסָקִים וְהַסִּבּוֹת שֶׁבַּמַּשָּׂא־וּמַתָּן, בְּוַדַּאי יֵשׁ בָּהֶם רָזִין עֲמֻקִּים, מַדּוּעַ הַשֵּׁם יִתְבָּרַךְ מְסַבֵּב שֶׁזֶּה יִתְפַּרְנֵס מִסְּחוֹרָה זֹאת וּבְמָקוֹם זֶה, וְזֶה מִסְּחוֹרָה אַחֶרֶת, וְהַכֹּל מֵאֵת הַשֵּׁם, וּבְכֻלָּם יֵשׁ רָזִין נִפְלָאִים, כִּי רַק הוּא יִתְבָּרַךְ יוֹדֵעַ לְפַרְנֵס כָּל אֶחָד, כְּפִי שֹׁרֶשׁ נִשְׁמָתוֹ וּכְפִי מַעֲשָׂיו בְּגִלְגּוּל זֶה וּבַגִּלְגּוּלִים הַקּוֹדְמִים. וּצְרִיכִין לְהַאֲמִין מְאֹד בָּזֶה, שֶׁבְּכָל דָּבָר יֵשׁ פְּנִימִיּוּת הַרְבֵּה, וְהַכֹּל בְּהַשְׁגָּחָה פְּרָטִית, וְהָעֵסֶק וְהַסִּבָּה בְּעַצְמָה שֶׁעוֹסֵק בָּהּ, צָרִיךְ לְהַשְׁלִיךְ הַכֹּל עַל הַשֵּׁם יִתְבָּרַךְ, כְּמוֹ שֶׁכָּתוּב: "גֹּל עַל ה' מַעֲשֶׂיךָ", וּכְתִיב: "הַשְׁלֵךְ עַל ה' יְהָבְךָ", לֵידַע כִּי הַסִּבָּה וְהָעֵסֶק הוּא רַק לְבוּשׁ וְכִסּוּי לִפְנִימִיּוּת חָכְמָתוֹ יִתְבָּרַךְ הַמְלֻבָּשׁ בְּכָל דָּבָר, מַה שֶּׁאִי אֶפְשָׁר לוֹ לְהָאָדָם לְהַשִּׂיג כְּלָל. וְעַל־כֵּן צָרִיךְ לִזָּהֵר לַעֲשׂוֹת הַמַּשָּׂא־וּמַתָּן בֶּאֱמוּנָה עַל־פִּי הַתּוֹרָה הַקְּדוֹשָׁה, וְלִבְלִי לִשְׁכֹּחַ אֶת הַשֵּׁם יִתְבָּרַךְ בִּשְׁעַת עֲשִׂיַּת הַמַּשָּׂא־וּמַתָּן; מִכָּל־שֶׁכֵּן שֶׁלֹּא יִתְחַכֵּם בְּחָכְמוֹת רָעוֹת וּמִרְמוֹת לִגַּע בְּמָמוֹן חֲבֵרוֹ, חַס וְשָׁלוֹם, אֲפִלּוּ שָׁוֶה פְּרוּטָה, כִּי הִיא לֹא תִצְלָח. וְעַל־כֵּן נִקְרָאִין הַגְּזֵלוֹת עַל שֵׁם הַלְּבוּשִׁין, כְּמוֹ שֶׁכָּתוּב: "וּבֶגֶד בּוֹגְדִים בָּגָדוּ", וְכֵן רֹב טִרְדַּת תַּאֲוַת מָמוֹן הוּא בִּשְׁבִיל הַבְּגָדִים וְהַמַּלְבּוּשֵׁי־כָבוֹד, לוֹ וּלְאִשְׁתּוֹ וּלְבָנָיו, וּבִפְרָט בְּעֵת הַנִּשּׂוּאִין, שֶׁכָּל רִבּוּי הַהוֹצָאָה הַיְתֵרָה הוּא עַל הַהַלְבָּשָׁה הַגְּדוֹלָה שֶׁנִּתְפַּשֵּׁט בִּזְמַנֵּנוּ, בַּעֲו?ֹנוֹתֵינוּ הָרַבִּים, עַד שֶׁהַרְבֵּה נַעֲשִׂים בַּעֲלֵי־חוֹבוֹת עַל־יְדֵי זֶה, וְיֵשׁ שֶׁבָּאִין לִגְזֵלוֹת גְּמוּרוֹת עַל־יְדֵי זֶה, כִּי הַמַּלְבּוּשִׁים מַטְרִידִין מְאֹד אֶת הָאָדָם, וְכַמְבֹאָר בְּמָקוֹם אַחֵר עַל פָּסוּק "וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ", שֶׁהַסִּטְרָא־אָחֳרָא תּוֹפֶסֶת אֶת הָאָדָם בִּבְגָדָיו דַּיְקָא. וְכֵן הַתַּנָּא הִתְחִיל מַסֶּכֶת בָּבָא־ מְצִיעָא, הַמְדַבֶּרֶת מֵעִנְיְנֵי מַשָּׂא־וּמַתָּן וְהַכְחָשׁוֹת שֶׁבֵּין אָדָם לַחֲבֵרוֹ, וְהִתְחִיל בְּדִין "שְׁנַיִם אוֹחֲזִין בְּטַלִּית", בְּטַלִּית דַּיְקָא, כִּי רֹב הַהַכְחָשׁוֹת שֶׁבָּאִים עַל־יְדֵי תַּאֲוַת מָמוֹן, הָעִקָּר הוּא מֵחֲמַת הַבְּגָדִים וְהַלְּבוּשִׁים, וְכָל זֶה מֵחֲמַת שֶׁאֵין מִסְתַּכְּלִים רַק עַל חִיצוֹנִיּוּת הַלְּבוּשִׁים וְלֹא עַל הַפְּנִימִיּוּת שֶׁבָּהֶם. וְעַל־כֵּן כְּשֶׁיֵּשׁ הַכְחָשׁוֹת צְרִיכִין שְׁבוּעָה, כִּי עַל־יְדֵי הַשְּׁבוּעָה נִתְגַּלִּין הַגַּוְנִין עִלָּאִין וְהַפְּנִימִיּוּת שֶׁבְּתוֹךְ לְבוּשֵׁי הַמָּמוֹן, כַּמְבֹאָר בִּפְנִים, וְעַל־ יְדֵי־זֶה בְּוַדַּאי יוֹדֶה עַל הָאֱמֶת וְיִתְתַּקֵּן הַכֹּל (שם אותיות ג ה ו ז). 
קל. מִצְוַת מְזוּזָה מְסֻגֶּלֶת לַעֲשִׁירוּת. וְעַל־כֵּן קוֹבְעִין אוֹתָהּ אֵצֶל הַפֶּתַח, כִּי דֶּרֶךְ שָׁם נִמְשֶׁכֶת הַהַשְׁפָּעָה, בִּבְחִינַת "וְדַלְתֵי שָׁמַיִם פָּתַח". וְהַחִיצוֹנִים הֵם סְמוּכִים תָּמִיד אֵצֶל מְקוֹם יְרִידַת הַשֶּׁפַע לִינֹק מִשָּׁם חַס וְשָׁלוֹם, וְהַמְּזוּזָה מְגָרֶשֶׁת אוֹתָם וּמַמְשֶׁכֶת הַהַשְׁפָּעָה רַק לִפְנִים אֶל הַקְּדֻשָּׁה (הל' נזקי שכנים ה"א,

). 
קמז. הָעֲשִׁירוּת נִמְשָׁךְ מִבְּחִינַת שְׂמֹאל, בְּחִינַת "בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד", וּשְׂמֹאל הוּא בְּחִינַת אַחַר הַבְּרִיאָה. וְכָל זְמַן שֶׁאֵין נִכְלָל חַס וְשָׁלוֹם שְׂמֹאל בְּיָמִין, דְּהַיְנוּ שֶׁאֵין נִכְלָל כְּלָלִיּוּת הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַבְּרִיאָה, שֶׁשָּׁם בְּחִינַת כֹּלָּא יַמִּינָא, אָז אִי אֶפְשָׁר לְקַבֵּל שֶׁפַע וּפַרְנָסָה, מֵאַחַר שֶׁרְחוֹקִין מֵהַשֹּׁרֶשׁ אֲשֶׁר הוּא מְחַיֶּה אֶת כֻּלָּם. וַאֲפִלּוּ מְעַט הַשֶּׁפַע שֶׁיּוֹרֵד אָז בְּהֶעְלֵם וּבְהַסְתָּרָה גְדוֹלָה עַל־יְדֵי הַסְתָּרַת הַשְׁגָּחָתוֹ יִתְבָּרַךְ בְּתוֹךְ דֶּרֶךְ הַטֶּבַע, גַּם זֶה הַמְעַט מְקַבְּלִין הָעַכּוּ"ם וְהָרְשָׁעִים, אֲבָל יִשְׂרָאֵל הַכְּשֵׁרִים פַּרְנָסָתָם מְעוּטָה מְאֹד. וְעַל־כֵּן עִקַּר הַמְשָׁכַת הַשֶּׁפַע לְיִשְׂרָאֵל הוּא כְּשֶׁשְּׂמֹאל נִכְלָל בְּיָמִין, הַיְנוּ כְּשֶׁאָנוּ זוֹכִין לְהִתְגַּבֵּר בֶּאֱמוּנַת הַהַשְׁגָּחָה שֶׁהַכֹּל מֵאִתּוֹ יִתְבָּרַךְ לְבַד, וְאֵין שׁוּם דֶּרֶךְ הַטֶּבַע בָּעוֹלָם כְּלָל, וְעַל־יְדֵי־זֶה אָנוּ זוֹכִין לְהַמְשִׁיךְ עֵינֵי הַשְׁגָּחָתוֹ יִתְבָּרַךְ עָלֵינוּ, וְאָז נִכְלָל אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה, שֶׁהוּא בְּחִינַת כְּלָלִיּוּת שְׂמֹאל בְּיָמִין, וְאָז הַשֵּׁם יִתְבָּרַךְ מַמְשִׁיךְ שֶׁפַע וְחִיּוּת לְהַבְּרִיאָה, כִּי עִקַּר שֹׁרֶשׁ הָעֶלְיוֹן שֶׁל הַשֶּׁפַע הוּא מִיָּמִין, כְּמוֹ שֶׁכָּתוּב: "נֹתֵן לֶחֶם לְכָל בָּשָׂר כִּי לְעוֹלָם חַסְדּוֹ", וְחֶסֶד הוּא יָמִין; רַק שָׁם בְּשָׁרְשׁוֹ הָעֶלְיוֹן, בִּבְחִינַת קֹדֶם הַבְּרִיאָה, שָׁם הַשֶּׁפַע דַּק וָזַךְ וּמְצֻחְצָח, עַד שֶׁאֵין שַׁיָּךְ לִקְרוֹתוֹ שָׁם בְּשֵׁם שֶׁפַע וַעֲשִׁירוּת; רַק כְּשֶׁאַחַר הַבְּרִיאָה, בְּחִינַת שְׂמֹאל, מְקַבֶּלֶת זֶה הָאוֹר עַל־יְדֵי הַהַשְׁגָּחָה, שֶׁעַל־יְדֵי־זֶה נִכְלָל אַחַר הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה, אָז נִצְטַיֶּרֶת הַשֶּׁפַע וְנִקְרֵאת בְּשֵׁם עֲשִׁירוּת, וְעַל־ כֵּן עִקַּר הָעֲשִׁירוּת מִשְּׂמֹאל. וּמֵחֲמַת שֶׁסּוֹד כְּלָלִיּוּת הַבְּרִיאָה בְּקֹדֶם הַבְּרִיאָה אִי אֶפְשָׁר לְהַשִּׂיג בְּשׁוּם דַּעַת, כִּי אִם בֶּאֱמוּנָה לְבַד, וְזֶה סוֹד קְרִיעַת יַם־סוּף, כַּמְבֹאָר בִּפְנִים, וּמִשָּׁם דַּיְקָא נִמְשָׁךְ הַפַּרְנָסָה, עַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל: קָשִׁין מְזוֹנוֹתָיו שֶׁל אָדָם כִּקְרִיעַת יַם־סוּף (הל' שלוחין ה"ג). 
קמח. כָּל הַמַּשָּׂא־וּמַתָּן הוּא בִּשְׁבִיל לְבָרֵר נִיצוֹצֵי הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁיֵּשׁ בְּכָל חֵפֶץ שֶׁבָּעוֹלָם, שֶׁבִּשְׁבִיל זֶה כָּל הַמַּשָּׂא־ וּמַתָּן, בִּבְחִינַת "נָשָׂאתָ וְנָתַתָּ בֶּאֱמוּנָה". וּמֵחֲמַת שֶׁעִקַּר תִּקּוּן הָאֱמוּנָה הוּא עַל־יְדֵי בֵּרוּר הַמְדַמֶּה, וְעִקַּר הַמַּשָּׂא־וּמַתָּן הוּא רַק בִּבְחִינַת הַמְדַמֶּה, כִּי כֹּחַ הַשֵּׂכֶל הָאֲמִתִּי שֶׁהוּא שֵׂכֶל הָעִיּוּנִי הוּא רָחוֹק מִכָּל זֶה, וְכָל הַשִּׁנּוּיִים שֶׁבַּמַּשָּׂא־וּמַתָּן, שֶׁלִּפְעָמִים אֵין הָאָדָם עוֹמֵד בְּדִבּוּרוֹ, הַכֹּל עַל־יְדֵי בִּלְבּוּל הַמְדַמֶּה, שֶׁהוּא בְּחִינַת פְּגַם אֱמוּנָה, עַל־כֵּן רֹב קִיּוּם הַמַּשָּׂא־וּמַתָּן שֶׁלֹּא יוּכְלוּ לְשַׁנּוֹת עוֹד הוּא עַל־יְדֵי קִנְיַן סוּדָר, שֶׁהוּא בַּלְּבוּשִׁים, שֶׁשָּׁרְשָׁם מִלְּבוּשִׁים הָעֶלְיוֹנִים, שֶׁהֵם בְּחִינַת הַדִּמְיוֹנוֹת הַקְּדוֹשׁוֹת שֶׁל הַנְּבִיאִים, בְּחִינַת "וּבְיַד הַנְּבִיאִים אֲדַמֶּה", שֶׁזֶּה בְּחִינַת בֵּרוּר הַמְדַמֶּה, שֶׁעַל־יָדוֹ נִתְתַּקֵּן וְנִשְׁלָם הָאֱמוּנָה הַקְּדוֹשָׁה, וְעַל־יְדֵי־ זֶה שׁוּב לֹא יְשַׁנּוּ עוֹד בְּהַמִּקָּח וּמִמְכָּר (שם הלכה ה,

). 
קנ. כָּל עִנְיְנֵי מַשָּׂא־וּמַתָּן וּמִקָּח וּמִמְכָּר הוּא לְהַעֲלוֹת הַקְּדֻשּׁוֹת הַנְּפוּלוֹת הַמְלֻבָּשׁוֹת בָּהֶם. וּכְשֶׁמַּעֲלִין אֵלּוּ הַנִּיצוֹצוֹת הַקְּדוֹשׁוֹת, וְהֵם צְרִיכִין לַעֲלוֹת מִדַּרְגָּא לְדַרְגָּא; וְזֶה יָדוּעַ, שֶׁבְּכָל מַדְרֵגָה יֵשׁ קְלִפָּה הַקּוֹדֶמֶת לַפֶּרִי, שֶׁזֶּה בְּחִינַת הַבִּלְבּוּלִים וְהַדִּמְיוֹנוֹת שֶׁצְּרִיכִין לְשַׁבְּרָם קֹדֶם שֶׁעוֹלִין לְהַמַּדְרֵגָה הָעֶלְיוֹנָה, עַל־כֵּן אֵין הַמִּקָּח נִגְמָר בִּדְבָרִים, כִּי יְכוֹלִין עֲדַיִן אֵלּוּ הַדִּמְיוֹנוֹת וְהַקְּלִפּוֹת לְהִתְגַּבֵּר, וְלֹא יַנִּיחוּ לְהַנִּיצוֹצוֹת הַקְּדוֹשׁוֹת לַעֲלוֹת לְהַמַּדְרֵגָה הָעֶלְיוֹנָה, עַד שֶׁעַל־יְדֵי־זֶה יִתְבַּטֵּל הַמִּקָּח לְגַמְרֵי. וְעַל־כֵּן עִקַּר הַקִּנְיָן מִדְּאוֹרַיְתָא הוּא מְעוֹת כֶּסֶף, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כִּי שָׁם בְּהַמָּמוֹן דִּקְדֻשָּׁה שֶׁל יִשְׂרָאֵל מְאִירִין הַגַּוְנִין עִלָּאִין, שֶׁזֶּה בְּחִינַת הִתְגַּלּוּת גְּדֻלַּת הַבּוֹרֵא, שֶׁעַל־ יְדֵי־זֶה מְשַׁבְּרִין וּמְבַטְּלִין אֵלּוּ הַקְּלִפּוֹת וְהַדִּמְיוֹנוֹת. רַק אַף־עַל־פִּי־כֵן, מֵחֲמַת שֶׁלִּפְעָמִים אֵין מְאִירִין הַגַּוְנִין עִלָּאִין אֲפִלּוּ בְּמָמוֹן יִשְׂרָאֵל, מֵחֲמַת שֶׁאֵין מְקַיֵּם מִצְוַת צְדָקָה מִמָּמוֹנוֹ כָּרָאוּי, עַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל שֶׁאֵין מָעוֹת קוֹנוֹת, רַק קִנְיָנִים אֲחֵרִים, כַּמְבֹאָר בִּפְנִים (הלכות מקח וממכר הלכה ב; הל' מתנה הלכה ד). 
קנא. כְּשֶׁנִּכְנָס הָאָדָם לְתוֹךְ הַמַּשָּׂא־וּמַתָּן, שֶׁשָּׁם נֶאֱחָזִים הַקְּלִפּוֹת וְהַסִּטְרָא־ אָחֳרָא וְסוֹבְבִים הַנִּיצוֹצוֹת הַקְּדוֹשׁוֹת שֶׁבְּתוֹךְ הַמַּשָּׂא־וּמַתָּן, זֶה בְּחִינַת יְרִידָה לְגָלוּת מִצְרָיִם. וַאֲזַי אִי אֶפְשָׁר לוֹ לָאָדָם לַעֲמֹד שָׁם לַעֲשׂוֹת פְּעֻלָּתוֹ בִּשְׁלֵמוּת, לְבָרֵר הַנִּיצוֹצוֹת מִשָּׁם וְלָצֵאת מִשָּׁם בְּשָׁלוֹם, כִּי אִם עַל־יְדֵי שֶׁמְּקַשֵּׁר עַצְמוֹ אָז לְהַצַּדִּיק הַדּוֹר הָאֲמִתִּי שֶׁהוּא בְּחִינַת יוֹסֵף, שֶׁכָּל הַמְּכִירוֹת וְהַמִּסְחָרִים וְהַקִּנְיָנִים שֶׁבָּעוֹלָם כֻּלָּם נַעֲשִׂים בִּשְׁלֵמוּת עַל־יְדֵי הַצַּדִּיק הַזֶּה, בִּבְחִינַת "וְכָל הָאָרֶץ בָּאוּ מִצְרַיְמָה אֶל יוֹסֵף לִשְׁבֹּר וְכוּ'" (שם ה"ג

). 
קנב. כָּל הַנִּיצוֹצוֹת הַנְּפוּלִין, קֹדֶם שֶׁנִּתְבָּרְרִין וְשָׁבִים לִמְקוֹמָם הֵם בְּחִינַת הֶעְדֵּר הַדַּעַת, מֵחֲמַת שֶׁהֵם בְּגָלוּת וְאֵינָם בִּמְקוֹמָן, וַאֲזַי הֵם בִּבְחִינַת שֶׁפַע שֶׁל בְּהֵמָה, שֶׁהוּא בְּחִינַת הֶעְדֵּר הַדָּעַת. וְזֶה בְּחִינַת כָּל הַמַּשָּׂא־וּמַתָּן וְכָל הַמִּקָּח וְהַמִּמְכָּר, שֶׁצָּרִיךְ הַחֵפֶץ וְהַסְּחוֹרָה לַעֲבֹר וְלֵילֵךְ מִזֶּה לָזֶה וּמִזֶּה לָזֶה עַד שֶׁשָּׁב לִמְקוֹמוֹ הָרָאוּי, וְעַל־יְדֵי־זֶה דַיְקָא נִמְשֶׁכֶת הַשֶּׁפַע וְהַפַּרְנָסָה לְהָאָדָם, כִּי עַל־יְדֵי־זֶה נִתְבָּרְרִין הַנִּיצוֹצוֹת בְּכָל פַּעַם וְעוֹלִין מִגָּלוּתָם וְנִתְקָרְבִין לִמְקוֹמָם, וְעַל־יְדֵי־זֶה מִתְבָּרְרִין וְעוֹלִין מִבְּחִינַת שֶׁפַע שֶׁל בְּהֵמָה לִבְחִינַת שֶׁפַע שֶׁל אָדָם. וְזֶה בְּחִינַת אִסּוּר אוֹנָאָה, שֶׁאָסוּר לְהוֹנוֹת אֶת חֲבֵרוֹ בְּמָמוֹן וַאֲפִלּוּ בִּדְבָרִים, כִּי הָאוֹנָאָה הוּא פְּגַם הַדַּעַת, שֶׁמַּטְעֶה דַּעַת חֲבֵרוֹ וְעַל־יָדוֹ הוּא פּוֹגֵם בְּהַדַּעַת, וְאָז אֵינוֹ יָכוֹל לְבָרֵר הַשֶּׁפַע מִבְּחִינַת בְּהֵמָה, אַדְּרַבָּא עַל־יְדֵי־זֶה הוּא נוֹפֵל יוֹתֵר לִבְחִינַת שֶׁפַע שֶׁל בְּהֵמָה, פְּגַם הַדַּעַת כַּנַּ"ל (שם ה"ד, אותיות י טו). 
קנג. כָּל הַדּוֹחֵק אֶת הַשָּׁעָה, הַשָּׁעָה דוֹחַקְתּוֹ. כִּי כָל מַה שֶּׁמִּתְיַגֵּעַ יוֹתֵר אַחַר הַפַּרְנָסָה, וְאֵינוֹ בּוֹטֵחַ בְּהַשֵּׁם יִתְבָּרַךְ שֶׁיּוּכַל לְפַרְנְסוֹ בְּסִבָּה קַלָּה, וְאֵינוֹ נִמְשָׁךְ אַחַר הַדַּעַת הָאֲמִתִּי לְמַעֵט בְּעֵסֶק וְלַעֲסֹק בַּתּוֹרָה, עַל־כֵּן הַשָּׁעָה דוֹחַקְתּוֹ, כִּי מֵאַחַר שֶׁפּוֹגֵם בַּדַּעַת, עַל־יְדֵי־זֶה פַּרְנָסָתוֹ בִּכְבֵדוּת יוֹתֵר, כִּי אֵינוֹ יָכוֹל לְבָרֵר הַשֶּׁפַע מִבְּהֵמָה לְאָדָם, שֶׁמִּשָּׁם עִקַּר הַפַּרְנָסָה (שם

). 
קנט. שֹׁרֶשׁ בְּחִינַת הַמַּתָּנָה נִמְשָׁךְ מִבְּחִינַת הָאוֹצַר־מַתְּנַת־חִנָּם, שֶׁהוּא בְּחִינַת הַחֶסֶד־חִנָּם שֶׁעַל־יָדוֹ הָיָה קִיּוּם הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה. וְכֵן עַכְשָׁו בְּשָׁעָה שֶׁהָאָדָם בָּטֵל מִדִּבְרֵי־תוֹרָה מֵחֲמַת הַהֶכְרֵחַ, אוֹ גַם אֲנָשִׁים פְּשׁוּטִים לְגַמְרֵי שֶׁרְחוֹקִים מֵהַתּוֹרָה, הֵם מְקַבְּלִים חִיּוּתָם רַק מִזֹּאת הַבְּחִינָה, עַל־יְדֵי הָאִישׁ פָּשׁוּט הַגָּדוֹל שֶׁהוּא צַדִּיק, כַּמְבֹאָר בִּפְנִים. רַק מֵחֲמַת שֶׁבֶּאֱמֶת גַּם אָז קֹדֶם מַתַּן־תּוֹרָה הָיְתָה הַתּוֹרָה בִּמְצִיאוּת, רַק שֶׁהָיְתָה בְּהֶעְלֵם עֲדַיִן, וְעִקַּר קִיּוּם הָעוֹלָם אָז עַל־יְדֵי הַחֶסֶד הַנַּ"ל הָיָה רַק בִּשְׁבִיל שֶׁצָּפָה הַשֵּׁם יִתְבָּרַךְ שֶׁעֲתִידִין יִשְׂרָאֵל לְקַבֵּל הַתּוֹרָה וּלְהוֹצִיאָהּ מֵהֶעְלֵם אֶל הַגִּלּוּי, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: כָּל הָעוֹלָם הָיָה תָּלוּי עַד שִׁשִּׁי בְּסִיוָן שֶׁקִּבְּלוּ הַתּוֹרָה, שֶׁעַל־יְדֵי־זֶה נִתְבַּסֵּס הָעוֹלָם, כִּי עִקַּר קִיּוּם הָעוֹלָם עַל־יְדֵי הִתְגַּלּוּת הַתּוֹרָה. וְעַל־כֵּן כּוֹתְבִין בִּשְׁטַר־ מַתָּנָה: "כָּתְבוּהוּ בְּשׁוּקָא וְחָתְמוּהוּ וְכוּ', כִּי הֵיכִי דְּלָא לֶהֱוֵי מִלְּתָא דִטְמִירְתָּא", כְּדֵי לְפַרְסֵם וּלְגַלּוֹת כִּי גַם שָׁם בִּבְחִינַת מַתָּנָה הַתּוֹרָה נֶעְלֶמֶת בְּהֶעְלֵם וְהֶסְתֵּר, וְעִקַּר קִיּוּם הַמַּתָּנָה עַל־יְדֵי אוֹתִיּוֹת הַתּוֹרָה, שֶׁהֵם הַכֹּחַ וְהַחִיּוּת שֶׁבְּכָל דָּבָר כַּנַּ"ל, שֶׁעַל־יָדָם עִקַּר הַזְּכוּת שֶׁזּוֹכֶה אֶחָד מֵחֲבֵרוֹ; רַק כָּל־זְמַן שֶׁהֵן בְּהֶעְלֵם, אֲזַי אֵין לְהַמַּתָּנָה קִיּוּם, כִּי כָל זְמַן שֶׁהַתּוֹרָה בְּהֶעְלֵם אֵין לְהָעוֹלָם קִיּוּם, בִּבְחִינַת "רָאָה שֶׁאֵין הָעוֹלָם מִתְקַיֵּם", כִּי עִקַּר קִיּוּם הָעוֹלָם עַל־יְדֵי הִתְגַּלּוּת הַתּוֹרָה. עַל־כֵּן צְרִיכִין לִכְתֹּב גַּם בִּשְׁטַר־מַתָּנָה, שֶׁהָיְתָה הַמַּתָּנָה בְּפִרְסוּם וְלֹא בְהֶעְלֵם (שם; וע"ע מענין זה בהל' ג). 
קס. כָּל הַדְּבָרִים וְהַחֲפָצִים, כְּשֶׁיּוֹצְאִין מֵרְשׁוּת זֶה לִרְשׁוּת זֶה, שֶׁכָּל זֶה הוּא רַק בִּשְׁבִיל בֵּרוּר הַנִּיצוֹצוֹת הַקְּדוֹשׁוֹת שֶׁיֵּשׁ בְּכָל דָּבָר, זֶה בְּחִינַת שֶׁעוֹלִין מִדַּרְגָּא לְדַרְגָּא. וְאָז צְרִיכִין לְשַׁבֵּר הַקְּלִפָּה הַקּוֹדֶמֶת לַפֶּרִי, שֶׁזֶּה בְּחִינַת הַסִּבּוּבִים וְהַדִּמְיוֹנוֹת שֶׁמְּסַבְּבִין הַקְּדֻשָּׁה שֶׁבְּזוֹ הַמַּדְרֵגָה. וְעַל־כֵּן רֹב הַקִּנְיָנִים עַל־יְדֵי כֶּסֶף, כִּי עַל־יְדֵי הִתְגַּלּוּת הַגַּוְנִין עִלָּאִין הַמְלֻבָּשִׁין בְּכֶסֶף וְזָהָב דִּקְדֻשָּׁה, עַל־יְדֵי־זֶה מְשַׁבְּרִין הַקְּלִפָּה הַקּוֹדֶמֶת לַפֶּרִי. וְעַל־כֵּן הִזְהִירוּ רַבּוֹתֵינוּ זַ"ל עַל כָּל הַמִּצְו?ֹת, שֶׁצְּרִיכִין לִקְנוֹתָם בַּאֲגָר שְׁלִים, בְּכֶסֶף מָלֵא. וְעַל־כֵּן צְרִיכִין לְהַרְחִיק עַצְמוֹ מִלְּקַבֵּל מַתָּנוֹת, כְּמוֹ שֶׁכָּתוּב: "וְשׂוֹנֵא מַתָּנֹת יִחְיֶה", כִּי עֲלִיַּת הַקְּדֻשָּׁה קָשֶׁה שֶׁיִּהְיֶה בְּחִנָּם, כִּי אִם בְּכֶסֶף מָלֵא כַּנַּ"ל. עַיֵּן פְּנִים (שם ה"ד

). 
קסב. עִנְיַן מַה שֶּׁכְּשֶׁזּוֹכִין לְתַכְלִית נְקֻדַּת הָאֱמֶת, שֶׁיּוֹדְעִין שֶׁאֵין עוֹד מִלְּבַדּוֹ יִתְבָּרַךְ, אֵין עוֹד מַמָּשׁ, כִּי כֹלָּא קַמֵּהּ כְּאַיִן מַמָּשׁ וְכוּ', עַל־יְדֵי־זֶה אֲפִלּוּ כְּשֶׁפַּרְנָסָתוֹ עַל־יְדֵי שֶׁמְּקַבֵּל מֵחֲבֵרוֹ, אַף־עַל־פִּי־כֵן אֵינוֹ בִּכְלַל נִצְרָךְ לַבְּרִיּוֹת, כִּי יוֹדֵעַ בְּבֵרוּר שֶׁהַכֹּל מְקֻשָּׁר בּוֹ יִתְבָּרַךְ וְהַכֹּל מְקַבְּלִין רַק מִמֶּנּוּ יִתְבָּרַךְ לְבַד - עַיֵּן 'אֱמֶת', אוֹת סז. 
קסג. כָּל הָעֲסָקִים וְהַמַּשָּׂא וּמַתָּן וּמְלָאכוֹת שֶׁעוֹשִׂין הֵם בְּחִינַת עוֹלַם הָעֲשִׂיָּה. וּמֵחֲמַת שֶׁשָּׁם עִקַּר אֲחִיזַת הָעֲבוֹדָה זָרָה וְהַקְּלִפּוֹת, עַל־כֵּן צְרִיכִין לְחַזֵּק וּלְהִתְגַּבֵּר מְאֹד שֶׁלֹּא יִפֹּל לְהָעֲבוֹדָה זָרָה שֶׁל תַּאֲוַת מָמוֹן, חַס וְשָׁלוֹם. וְהָעִקָּר הוּא עַל יְדֵי צְדָקָה, שֶׁעַל יְדֵי זֶה מְשַׁבְּרִין תַּאֲוַת מָמוֹן (הל' אבידה ומציאה ה"ג,

). 
קסז. עִקַּר כְּבֵדוּת וְעֹל הַפַּרְנָסָה שֶׁמֻּנָּח עַל הָאָדָם כְּמַשּׂאוֹי כָּבֵד, הוּא בָּא רַק מֵחֲמַת כְּבֵדוּת הַמַּשּׂאוֹי שֶׁל עֲו?ֹנוֹת. וּכְפִי מַה שֶּׁזּוֹכֶה לָצֵאת מִמַּשּׂאוֹי כָּבֵד שֶׁל הָעֲו?ֹנוֹת שֶׁבָּאִים עַל־יְדֵי הָרוּחַ שְׁטוּת וְזוֹכֶה לְדַעַת, כְּמוֹ־כֵן פַּרְנָסָתוֹ מְעוֹפֶפֶת לוֹ בְּנָקֵל. וְעַל־כֵּן, עַל־יְדֵי שֶׁמְּרַחֲמִים עַל חֲבֵרוֹ בְּרַחֲמָנוּת אֲמִתִּי וּמְדַבְּרִים עִמּוֹ בְּיִרְאַת־שָׁמַיִם וּמַכְנִיסִין בּוֹ דַּעַת אֲמִתִּי, עַל־יְדֵי־זֶה מַמְשִׁיכִין לוֹ פַּרְנָסָה גַּם־כֵּן. וְכֵן עַל־יְדֵי שֶׁדָּנִין אֶת הָאָדָם לְכַף־זְכוּת וּמוֹצְאִין בּוֹ נְקֻדּוֹת טוֹבוֹת, שֶׁעַל־יְדֵי־זֶה מַכְנִיסִין אוֹתוֹ בֶּאֱמֶת לְכַף־זְכוּת וִיכוֹלִין לְהַחֲזִירוֹ בִּתְשׁוּבָה עַל יְדֵי זֶה, כַּמְבֹאָר בְּמָקוֹם אַחֵר, עַל יְדֵי זֶה בְּעַצְמוֹ מַמְשִׁיכִין לוֹ גַם כֵּן פַּרְנָסָה בְּרֶוַח (הל' פריקה וטעינה ה"ב). 
קסח. כְּפִי הַסֵּדֶר שֶׁנִּמְשָׁךְ הַחִיּוּת מֵאֶחָד הַפָּשׁוּט לְכָל פְּעֻלּוֹת מִשְׁתַּנּוֹת, רָאוּי שֶׁיִּתְנַהֵג הַכֹּל כְּסֵדֶר, כִּי אִתּוֹ יִתְבָּרַךְ לֹא יִבָּצֵר כָּל טוֹב, וְהוּא בְּרַחֲמָיו יִתְבָּרַךְ בָּרָא עוֹלָמוֹ רַק לְטוֹבָה. וְעִקַּר הַתִּקּוּן עַל־יְדֵי שַׁבָּת, כִּי מִשַּׁבָּת נִמְשָׁךְ שְׁבִיתָה וּנְיָחָא עַל כָּל פְּעֻלּוֹת מִשְׁתַּנּוֹת שֶׁעוֹשִׂין בִּימֵי הַחֹל, לְהַמְתִּיק וּלְבַטֵּל בְּחִינַת הָעַצְבוּת וְהָעַבְדוּת הַקָּשָׁה גַּם מֵעוֹבָדִין דְּחֹל, שֶׁיִּהְיוּ נַעֲשִׂין לוֹ כָּל הָעֲסָקִים וְכָל הָעֲשִׂיּוֹת כְּסֵדֶר בְּלִי יְגִיעָה וַעֲבוֹדָה קָשָׁה. אֲבָל כָּל אֶחָד כְּפִי מַה שֶּׁפּוֹגֵם בָּזֶה, שֶׁאֵינוֹ מִשְׁתַּדֵּל לְהַמְשִׁיךְ קְדֻשַּׁת שַׁבָּת לִימֵי הַחֹל וְאֵינוֹ מְגַלֶּה אַחְדוּת הַפָּשׁוּט מִתּוֹךְ פְּעֻלּוֹת מִשְׁתַּנּוֹת, כְּמוֹ־כֵן מִתְגַּבְּרִים עָלָיו רִבּוּיֵי הַשִּׁנּוּיִים שֶׁל הַפְּעֻלּוֹת מִשְׁתַּנּוֹת וְאֵינוֹ מִתְנַהֵג לוֹ כְּסֵדֶר, וּמִשָּׁם בָּאִים כָּל הַיִּסּוּרִים חַס וְשָׁלוֹם וְכָל הַטְּרָדוֹת וְהַיְגִיעוֹת וְהַכְּבֵדוּת שֶׁיֶּשׁ לוֹ בַּעֲסָקָיו. וְהַתִּקּוּן לָזֶה - לַעֲזֹב וּלְבַטֵּל מִלִּבּוֹ כָּל מִינֵי שִׂנְאָה וּמַחֲלֹקֶת, וּלְבַקֵּשׁ אַהֲבָה וְשָׁלוֹם עִם הַכֹּל, וְעַל־יְדֵי־זֶה נִתְגַּלֶּה גַם־כֵּן בְּחִינַת אַחְדוּת הַפָּשׁוּט מִתּוֹךְ פְּעֻלּוֹת מִשְׁתַּנּוֹת, וְאָז נִתְבַּטֵּל מִמֶּנּוּ כָּל הַכְּבֵדוּת וְהַיְגִיעוֹת וְהַיִּסּוּרִים, וְנִמְשָׁךְ נְיָחָא עַל הַכֹּל (שם ה"ד

). 
קעח. הַמָּמוֹן נִמְשָׁךְ בְּשָׁרְשׁוֹ מִבְּחִינַת הַצִּמְצוּם שֶׁל חָלָל הַפָּנוּי, כַּמְבֹאָר בִּפְנִים. וּמֵחֲמַת שֶׁבְּהֶחָלָל הַפָּנוּי הַקְּדֻשָּׁה וְהָאֱלָקוּת נֶעְלָם שָׁם מְאֹד, עַד שֶׁמִּשָּׁם, הַיְנוּ מִבְּחִינַת הַצִּמְצוּם וְהַהַעְלָמָה וְהַסְתָּרַת אֱלָקוּתוֹ יִתְבָּרַךְ שֶׁיֵּשׁ שָׁם, מִשָּׁם נִמְשָׁכִין שֹׁרֶשׁ הִשְׁתַּלְשְׁלוּת כָּל הַדִּינִים רַחֲמָנָא לִצְּלַן, שֶׁמִּשָּׁם יְנִיקַת כָּל הַכְּפִירוֹת רַחֲמָנָא לִצְּלַן, עַל־כֵּן בְּהַמָּמוֹן שֶׁנִּמְשָׁךְ בְּשָׁרְשׁוֹ מִשָּׁם, תְּחוּבִים בּוֹ גַם־כֵּן כָּל הַשִּׁבְעִים עֲבוֹדוֹת זָרוֹת וְכָל מִינֵי כְּפִירוֹת רַחֲמָנָא לִצְּלַן. וּמֵחֲמַת שֶׁכָּל בְּחִינַת כְּפִירָה, שֶׁהוּא בְּחִינַת עֲבוֹדָה זָרָה, כָּלוּל מִשְׁתֵּי בְּחִינוֹת כְּפִירוֹת, כִּי יֵשׁ כְּפִירוֹת כָּאֵלּוּ שֶׁנִּמְשָׁכִין רַק מִבְּחִינַת שְׁבִירַת כֵּלִים (שֶׁנִּמְשָׁךְ גַּם־כֵּן בְּשָׁרְשׁוֹ עַל־ יְדֵי תֹּקֶף הַצִּמְצוּם וְהַדִּין שֶׁבִּבְחִינַת חָלָל הַפָּנוּי), וְיֵשׁ כְּפִירוֹת כָּאֵלּוּ שֶׁיְּנִיקָתָם מִבְּחִינַת הַעְלָמָה וְהַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי. עַל־כֵּן הַנּוֹפֵל לְתַאֲוַת מָמוֹן, רַחֲמָנָא לִצְּלַן, הַשְּׁכִינָה צוֹוַחַת עָלָיו ק"מ קוֹלוֹת, שֶׁהֵם שְׁנֵי פְּעָמִים שִׁבְעִין קָלִין, כְּנֶגֶד הַבְּחִינַת שִׁבְעִים מִינֵי עֲבוֹדוֹת זָרוֹת וּכְפִירוֹת הַתְּחוּבִים וּכְלוּלִים בְּתַאֲוַת מָמוֹן, שֶׁכָּל מִין וָמִין כָּלוּל מִשְּׁנֵי בְּחִינוֹת כַּנַּ"ל. וּמֵחֲמַת שֶׁשָּׁם בְּהֶחָלָל הַפָּנוּי אִי אֶפְשָׁר לִמְצֹא וּלְהַשִּׂיג שָׁם אֱלָקוּתוֹ יִתְבָּרַךְ עַל־יְדֵי שׁוּם שֵׂכֶל, רַק עַל־יְדֵי אֱמוּנָה, שֶׁצְּרִיכִין לְהַאֲמִין שֶׁגַּם הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי בְּעַצְמוֹ נִמְשָׁךְ גַּם־כֵּן רַק מֵהַשֵּׁם יִתְבָּרַךְ, וְגַם שָׁם נֶעְלָם אֱלָקוּתוֹ יִתְבָּרַךְ, וְכָל הֶחָלָל הַפָּנוּי וְהַצִּמְצוּם לֹא הָיָה רַק בִּשְׁבִיל הִתְגַּלּוּת, הַיְנוּ בִּכְדֵי שֶׁיִּהְיֶה מָקוֹם לַבְּרִיאָה כְּדֵי לְגַלּוֹת אֱלָקוּתוֹ בָּעוֹלָם, כִּי בְּלֹא זֶה לֹא הָיָה אֶפְשָׁר לְגַלּוֹת אֱלָקוּתוֹ, כִּי הָיָה הַכֹּל אֵין סוֹף, כַּמְבֹאָר בִּפְנִים; וְעַל־כֵּן כְּמוֹ־כֵן מַמָּשׁ עִקַּר תִּקּוּן וּשְׁבִירַת תַּאֲוַת מָמוֹן הוּא רַק עַל־יְדֵי אֱמוּנָה, שֶׁצָּרִיךְ לְהַאֲמִין בֶּאֱמוּנָה שְׁלֵמָה שֶׁבְּכָל הָעֲסָקִים וְהַמַּשָּׂא־וּמַתָּן שֶׁעוֹשֶׂה בִּשְׁבִיל מָמוֹן נֶעְלָם וְנִמְצָא שָׁם אֱלָקוּתוֹ יִתְבָּרַךְ, וְהַמָּמוֹן בְּעַצְמוֹ הוּא רַק מֵהַשֵּׁם יִתְבָּרַךְ, וְלֹא נִתַּן לוֹ הַמָּמוֹן כִּי אִם כְּדֵי שֶׁיִּזְכֶּה עַל־יָדוֹ לְחַיֵּי עוֹלָם, לִתֵּן צְדָקָה וְלַעֲסֹק בְּתוֹרָה וּמִצְו?ֹת, שֶׁזֶּה מַמָּשׁ בְּחִינַת הָאֱמוּנָה שֶׁבְּהֶחָלָל הַפָּנוּי בְּעַצְמוֹ, שֶׁמַּאֲמִין שֶׁכָּל הַצִּמְצוּם הָיָה רַק בִּשְׁבִיל הִתְגַּלּוּת, אֲבָל הָאֱמֶת גַּם שָׁם נִמְצָא אֱלָקוּתוֹ יִתְבָּרַךְ כַּנַּ"ל, וְעִקַּר הַשְּׁלֵמוּת הוּא כְּשֶׁאֵין מַקְפִּיד עַל מָמוֹנוֹ בִּשְׁבִיל הַשֵּׁם יִתְבָּרַךְ, וּמְפַזֵּר מָמוֹן הַרְבֵּה בִּשְׁבִיל צְדָקָה וּמִצְו?ֹת, נִמְצָא שֶׁמַּאֲמִין שֶׁגַּם הַמָּמוֹן בְּעַצְמוֹ, שֶׁהוּא בְּחִינַת הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, נִמְשָׁךְ גַּם־כֵּן מֵהַשֵּׁם יִתְבָּרַךְ, מֵאַחַר שֶׁמְּפַזֵּר הַמָּמוֹן בִּשְׁבִילוֹ יִתְבָּרַךְ. וְזֶה עִקַּר יְסוֹד כָּל הַמִּצְו?ֹת, שֶׁשָּׁרְשָׁם אֱמוּנָה. וְעַל־כֵּן עִקַּר שְׁלֵמוּת הַמִּצְו?ֹת כְּשֶׁקּוֹנִים אוֹתָם בְּכֶסֶף מָלֵא (כַּמְבֹאָר בַּזֹּהַר הַקָּדוֹשׁ), כִּי זֶה בְּחִינַת הָאֱמוּנָה הַשְּׁלֵמָה, שֶׁצְּרִיכִין לְהַאֲמִין שֶׁגַּם הֶחָלָל הַפָּנוּי בְּעַצְמוֹ מָלֵא מֵאֱלָקוּתוֹ יִתְבָּרַךְ, שֶׁזֶּה עִקַּר יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, כִּי עַל־יְדֵי־זֶה נִתְתַּקֵּן מִמֵּילָא בְּחִינַת שְׁבִירַת כֵּלִים גַּם־כֵּן וְנִתְגַּלֶּה אֱלָקוּתוֹ יִתְבָּרַךְ בְּכָל מָקוֹם, כַּמְבֹאָר בִּפְנִים. וְזֶה בְּחִינַת מַה שֶּׁאַבְרָהָם אָבִינוּ קָנָה אֶת מְעָרַת הַמַּכְפֵּלָה בְּכֶסֶף מָלֵא דַיְקָא, וְכֵן דָּוִד הַמֶּלֶךְ, עָלָיו הַשָּׁלוֹם, כְּשֶׁקָּנָה גֹּרֶן אֲרַוְנָה, שֶׁהוּא מְקוֹם הַבֵּית־הַמִּקְדָּשׁ, כִּי לְהוֹצִיא הַקְּדֻשָּׁה מֵהֶעְלֵם אֶל הַגִּלּוּי, שֶׁזֶּה בְּחִינַת לְגַלּוֹת הַקְּדֻשָּׁה הַנֶּעְלֶמֶת בְּתוֹךְ הֶחָלָל הַפָּנוּי, זֶה אִי אֶפְשָׁר, כִּי אִם עַל־יְדֵי שְׁלֵמוּת הָאֱמוּנָה, וְעִקַּר שְׁלֵמוּת הָאֱמוּנָה הוּא עַל־ יְדֵי שֶׁמְּפַזְּרִין מָמוֹן הַרְבֵּה בִּשְׁבִיל הַדָּבָר שֶׁבִּקְדֻשָּׁה כַּנַּ"ל (שם אותיות ח י יא יג). 
קעט. עַל יְדֵי שֶׁמַּאֲמִין בִּשְׁלֵמוּת שֶׁכָּל הַמָּמוֹן וְהַחֲפָצִים, הַכֹּל נִמְשָׁךְ רַק מֵהַשֵּׁם יִתְבָּרַךְ, וְלֹא בְכֹחַ יִגְבַּר אִישׁ, עַל יְדֵי זֶה נִשְׁמָר הַמָּמוֹן מִכָּל הַהֶזֵּקוֹת שֶׁאֵין בְּיַד הָאָדָם לְהִשָּׁמֵר מֵהֶם (שם

). 
קפא. אָמְרוּ רַבּוֹתֵינוּ זַ"ל: הַרְחֵק מִן הַפִּקְדוֹנוֹת. כִּי הַשְּׁמִירָה קָשָׁה מְאֹד, כִּי הַמַּזִּיקֵי עָלְמָא אוֹרְבִים תָּמִיד עַל כָּל דָּבָר לְקַלְקֵל וּלְהַזִּיק, חַס וְשָׁלוֹם, וְהֵם נִקְרָאִים חִיצוֹנִים, וְעִקַּר שְׁלִיטָתָם וַאֲחִיזָתָם הוּא רַק בִּבְחִינַת עֲבוֹדוֹת חִיצוֹנִיּוֹת, שֶׁהוּא בְּחִינַת מָמוֹנוֹ וַחֲפָצָיו שֶׁל אָדָם, שֶׁהֵם בִּבְחִינַת חִיצוֹנִיּוּת, בְּחִינַת "שְמַח זְבוּלֻן בְּצֵאתֶךָ", וְשָׁם אוֹרְבִים הַחִיצוֹנִים לְהַשְׁחִית וּלְקַלְקֵל, חַס וְשָׁלוֹם. וְעַל־כֵּן קָשֶׁה עַל הָאָדָם לִשְׁמֹר אֲפִלּוּ חֶפְצֵי עַצְמוֹ, וּמִכָּל־שֶׁכֵּן שֶׁצָּרִיךְ לְהִתְרַחֵק מִלְּקַבֵּל עָלָיו שְׁמִירַת פִּקְדוֹנוֹת שֶׁל אֲחֵרִים. כִּי כְּמוֹ שֶׁעִקַּר הַשְּׁמִירָה בְּגַשְׁמִיּוּת הוּא שֶׁיִּסְתַּכֵּל עַל הַדָּבָר בְּעֵינָא פְקִיחָא וְלֹא יַעְלִים עַיִן מִמֶּנּוּ, כְּמוֹ־כֵן עִקַּר הַשְּׁמִירָה בְּשָׁרְשָׁהּ בְּרוּחָנִיּוּת הוּא רַק עַל־יְדֵי שֶׁזּוֹכֶה לְהִסְתַּכֵּל הֵיטֵב בְּעֵינָא פְקִיחָא עַל פְּנִימִיּוּת הַשֵּׂכֶל דִּקְדֻשָּׁה שֶׁיֵּשׁ בְּכָל דָּבָר, וּלְקַשֵּׁר כָּל הַדְּבָרִים וְהַחֲפָצִים אֶל הַשֵּׂכֶל וְהַדַּעַת הָאֲמִתִּי, שֶׁעַל־יְדֵי־זֶה מַעֲלֶה כָּל הַדְּבָרִים מִבְּחִינַת חִיצוֹנִיּוּת וּמְקַשֵּׁר אוֹתָם אֶל הַפְּנִימִיּוּת, שֶׁהוּא הַחָכְמָה דִקְדֻשָּׁה, שֶׁהוּא שֹׁרֶשׁ הַכֹּל, וְשָׁם אֵין שׁוּם שְׁלִיטָה וַאֲחִיזָה לְמַזִּיקֵי עָלְמָא שֶׁהֵם הַחִיצוֹנִים כַּנַּ"ל. וְעַל־ כֵּן עַל־יְדֵי־זֶה נִשְׁמְרִים מִכָּל הַהֶזֵּקוֹת. וְעַל־ כֵּן הַשְּׁמִירָה הִיא עֲבוֹדָה קָשָׁה, כִּי זֶה עִקַּר הַמִּלְחָמָה וְהַיְגִיעָה שֶׁל כָּל אָדָם בְּזֶה הָעוֹלָם, שֶׁלֹּא יִהְיֶה נִמְשָׁךְ אַחַר גַּשְׁמִיּוּת כָּל דָּבָר, רַק לְהַעֲלוֹת וּלְקַשֵּׁר כָּל דָּבָר אֶל פְּנִימִיּוּת הַשֵּׂכֶל שֶׁיֵּשׁ בְּכָל דָּבָר. וְעַל־כֵּן קָרְאָה הַתּוֹרָה הַקְּדוֹשָׁה לְהַשּׁוֹמֵר בְּשֵׁם 'בַּעַל הַבַּיִת', כְּמוֹ שֶׁכָּתוּב: "וְנִקְרַב בַּעַל הַבַּיִת אֶל הָאֱלֹקִים", וּפֵרְשׁוּ רַבּוֹתֵינוּ זַ"ל, שֶׁהוּא הַשּׁוֹמֵר, שֶׁנִּקְרָא בַּעַל הַבַּיִת, כִּי בָּזֶה רִמְּזָה לָנוּ הַתּוֹרָה הַקְּדוֹשָׁה, שֶׁעִקַּר הַשְּׁמִירָה הוּא עַל־יְדֵי שֶׁמְּקַשְּׁרִין הַחִיצוֹנִיּוּת אֶל פְּנִימִיּוּת הַשֵּׂכֶל וְהַחִיּוּת דִּקְדֻשָּׁה שֶׁיֵּשׁ בְּכָל דָּבָר, שֶׁזֶּה בְּחִינַת בַּיִת, שֶׁהוּא בִּבְחִינַת פְּנִימִיּוּת כְּנֶגֶד מְקוֹמוֹת שֶׁמִּבַּחוּץ, וּלְשָׁם מַכְנִיס הָאָדָם כָּל חֲפָצָיו וְשָׁם מָקוֹם מְשֻׁמָּר, כִּי זֶה עִקַּר הַשְּׁמִירָה, עַל־יְדֵי שֶׁמַּכְנִיסִין וּמַעֲלִין כָּל דָּבָר מִחוּץ לִפְנִים וּמְקַשְּׁרִין אוֹתוֹ לְשָׁרְשׁוֹ, שֶׁהוּא הַחָכְמָה דִקְדֻשָּׁה, שֶׁהוּא עִקַּר הַפְּנִימִיּוּת כַּנַּ"ל (שם אותיות יד טז). 
קפב. עִקַּר הַשְּׁמִירָה שֶׁל כָּל הָעוֹלָם, שֶׁיִּהְיוּ נִשְׁמָרִים עִם כָּל עֲשִׁירוּתָם וְחֶפְצֵיהֶם מִכָּל מִינֵי הֶזֵּקוֹת שֶׁבָּעוֹלָם, הַכֹּל נִמְשָׁךְ עַל־יְדֵי אֱמוּנַת חֲכָמִים אֲמִתִּיִּים, הָעוֹסְקִים תָּמִיד לְחַדֵּשׁ בַּתּוֹרָה וּלְהַרְבּוֹת סְפָרִים קְדוֹשִׁים בְּהַתּוֹרָה, שֶׁעַל־יְדֵי־זֶה נִשְׁלֶמֶת הַתּוֹרָה עַד שֶׁנִּכְלֶלֶת בִּבְחִינַת שֵׂכֶל הַכּוֹלֵל, שֶׁעַל־יְדֵי־זֶה נִמְתָּקִין כָּל הַדִּינִים שֶׁבָּעוֹלָם וְנִתְבַּטְּלִין כָּל מִינֵי הֶזֵּקוֹת וְחֶסְרוֹנוֹת שֶׁשָּׁרְשָׁם מִבְּחִינַת דִּינִים הַנַּ"ל. אַךְ צְרִיכִין לָזֶה, שֶׁיִּהְיֶה אַהֲבָה וְשָׁלוֹם גָּדוֹל בֵּין יִשְׂרָאֵל, כַּמְבֹאָר בִּפְנִים (שם הלכה ה,

). 
קפח. עִקַּר חֶסְרוֹן הַפַּרְנָסָה הוּא מֵחֲמַת חֶסְרוֹן הַדַּעַת, כִּי כָּל אֶחָד כְּפִי שְׁלֵמוּת דַּעְתּוֹ, כְּמוֹ־כֵן הוּא מִתְחַזֵּק בְּבִטָּחוֹן וְאֵין לוֹ דַּאֲגַת הַפַּרְנָסָה. כִּי בֶּאֱמֶת אֲפִלּוּ עַכְשָׁו בַּגָּלוּת הַמַּר הַזֶּה וּבְדַחֲקוּת הַפַּרְנָסָה, בִּפְרָט עֹצֶם דַּחֲקוּת פַּרְנָסָה שֶׁל הָעֲנִיִּים וְאֶבְיוֹנִים, אַף־עַל־פִּי־כֵן אֵין עֵצָה וְתַחְבּוּלָה כִּי אִם בִּטָּחוֹן חָזָק, וּכְמוֹ שֶׁאָמַר רַבֵּנוּ, זֵכֶר צַדִּיק וְקָדוֹשׁ לִבְרָכָה, בְּזֶה הַלָּשׁוֹן: 
קצא. כָּל הַהֶפְסֵדוֹת וְהֶזֵּקוֹת נִמְשָׁכִין מִן הַקְּלִפּוֹת שֶׁהֵם מַזִּיקֵי עָלְמָא, וְכָל הַקְּלִפּוֹת וְהַמַּזִּיקֵי עָלְמָא נִמְשָׁכִין מִן הַכְּפִירוֹת וְאֶפִּיקוֹרְסוּת שֶׁל חַכְמֵי הַטֶּבַע הַכּוֹפְרִים בָּרָצוֹן, כִּי כְּפִירוֹת וְאֶפִּיקוֹרְסוּת הוּא שֹׁרֶשׁ הַסִּטְרָא־אָחֳרָא וְהַקְּלִפּוֹת, כִּי הַיֵּצֶר הָרָע נִקְרָא 'אֵל אַחֵר', כְּפִירוֹת. וְעַל־כֵּן עִקַּר הַשְּׁמִירָה מִכָּל הַהֶזֵּקוֹת הוּא עַל־יְדֵי אֱמוּנַת הָרָצוֹן, כִּי כָּל מַה שֶּׁמַּאֲמִין בְּיוֹתֵר בִּבְחִינַת הָרָצוֹן, שֶׁהַכֹּל בִּרְצוֹנוֹ יִתְבָּרַךְ וְאֵין שׁוּם חִיּוּב הַטֶּבַע כְּלָל, עַל־יְדֵי־זֶה נִדְחִין הַכְּפִירוֹת וְנִתְבַּטְּלִין כָּל הַקְּלִפּוֹת שֶׁל מַזִּיקֵי עָלְמָא הַנִּמְשָׁכִין מֵהֶם, וְעַל־יְדֵי־זֶה הוּא נִשְׁמָר מִכָּל רָע. וְעַל־כֵּן מִדַּת אֱמוּנָה נִקְרֵאת 'שִׁמּוּר' כַּיָּדוּעַ, כִּי עִקַּר הַשְּׁמִירָה הוּא עַל־ יְדֵי אֱמוּנָה כַּנַּ"ל (הל' שומר שכר ה"ב,

). 
קצה. מִי שֶׁעוֹסֵק בַּתּוֹרָה תָּמִיד בֶּאֱמֶת, אֵין צָרִיךְ שׁוּם שְׁמִירָה, כִּי הַתּוֹרָה תִּשְׁמֹר עָלֶיךָ וְכוּ', וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל: תַּלְמִידֵי־חֲכָמִים אֵין צְרִיכִין נְטִירוּתָא. אַךְ אִי אֶפְשָׁר שֶׁיִּהְיֶה הָאָדָם דָּבוּק בְּהַתּוֹרָה תָּמִיד יוֹם וָלַיְלָה בְּלִי הֶפְסֵק רֶגַע, אֲפִלּוּ הַמַּתְמִידִים הַרְבֵּה בַּתּוֹרָה, מִכָּל־שֶׁכֵּן שֶׁיֵּשׁ שֶׁלּוֹמְדִים מְעַט וּמְבַטְּלִים הַרְבֵּה בִּשְׁבִיל פַּרְנָסָה וְכַדּוֹמֶה; מִכָּל־שֶׁכֵּן שֶׁיֵּשׁ אֲנָשִׁים פְּשׁוּטִים שֶׁאֵינָם לוֹמְדִים כְּלָל, וְאִם־כֵּן מֵהֵיכָן יְקַבְּלוּ הֵם שְׁמִירָה? אַךְ עִקַּר חִיּוּתָם וּשְׁמִירָתָם בְּגוּף וְנֶפֶשׁ וּמָמוֹן הוּא רַק עַל־ יְדֵי הַצַּדִּיק הַגָּדוֹל, שֶׁהוּא גַם־כֵּן לִפְעָמִים אִישׁ פָּשׁוּט, וְכַמְבֹאָר בִּפְנִים, וְאָז הוּא מְחַיֶּה אֶת עַצְמוֹ מִבְּחִינַת קִיּוּם הָעוֹלָם קֹדֶם מַתַּן־ תּוֹרָה, שֶׁהָיָה רַק עַל־יְדֵי חֶסֶד חִנָּם לְבַד, בְּחִינַת הָאוֹצַר־מַתְּנַת־חִנָּם, שֶׁזֶּה בְּחִינַת הַתּוֹרָה הַנֶּעְלֶמֶת בְּדֶרֶךְ־אֶרֶץ. וְעַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל: טוֹב תּוֹרָה עִם דֶּרֶךְ־אֶרֶץ, שֶׁצְּרִיכִין שְׁנֵיהֶם דַּיְקָא וְכַמְבֹאָר בִּפְנִים. וְעַל־כֵּן זֶה הַצַּדִּיק שׁוֹמֵר אֶת כָּל הָעוֹלָם תָּמִיד מִכָּל מַזִּיקֵי עָלְמָא, אֲפִלּוּ בְּעֵת שֶׁבְּטֵלִים מִן הַתּוֹרָה וְעוֹסְקִים בְּדֶרֶךְ־אֶרֶץ. אַךְ מֵאַחַר שֶׁכָּל הַחִיּוּת וְהַקִּיּוּם וְהַשְּׁמִירָה אָז הוּא עַל־יְדֵי הַחֶסֶד חִנָּם, שֶׁעַל־יָדוֹ הָיָה קִיּוּם הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה, עַל־כֵּן צְרִיכִין לְהַרְבּוֹת בִּצְדָקָה וָחֶסֶד, כְּדֵי שֶׁיִּהְיֶה לוֹ כֹּחַ לְעוֹרֵר וּלְהַמְשִׁיךְ עָלָיו בְּחִינַת הַחֶסֶד חִנָּם הַנַּ"ל, שֶׁעַל־יְדֵי־זֶה עִקַּר חִיּוּתוֹ וּשְׁמִירָתוֹ. וְעַל־כֵּן הַשּׁוֹמֵר חִנָּם פָּטוּר מֵהַכֹּל, אֲפִלּוּ מִגְּנֵבָה וַאֲבֵדָה, כִּי מֵאַחַר שֶׁעָשָׂה חֶסֶד חִנָּם עִם בַּעַל הַחֵפֶץ וְשׁוֹמֵר לוֹ בְּחִנָּם, עַל־כֵּן אֵין אַחֲרָיוּת הַדָּבָר עָלָיו וְאֵין תּוֹלִין בּוֹ הַהֶזֵּק, כִּי מִצִּדּוֹ אֵין שׁוּם הֶזֵּק, מֵאַחַר שֶׁעָשָׂה חֶסֶד חִנָּם, שֶׁמִּשָּׁם עִקַּר הַשְּׁמִירָה שֶׁנִּמְשָׁךְ עַל־יְדֵי הַצַּדִּיק־הָאֱמֶת שֶׁשּׁוֹמֵר וּמְחַיֶּה הַכֹּל עַל־יְדֵי הַחֶסֶד חִנָּם. וְעַל־כֵּן הַשּׁוֹאֵל חַיָּב בַּכֹּל וְכָל אַחֲרָיוּת הַחֵפֶץ עַל הַשּׁוֹאֵל, כִּי אֵין אָנוּ תּוֹלִין הַהֶזֵּק בְּהַמַּשְׁאִיל, מֵאַחַר שֶׁעָשָׂה חֶסֶד חִנָּם עִם הַשּׁוֹאֵל וְהִשְׁאִיל לוֹ חֶפְצוֹ בְּחִנָּם, שֶׁעַל־יְדֵי־זֶה נִמְשָׁךְ הַחֶסֶד חִנָּם הַנַּ"ל, שֶׁמִּשָּׁם כָּל הַשְּׁמִירָה כַּנַּ"ל (שם אותיות ב ג ד ה). 
קצו. מִי שֶׁפּוֹגֵם בְּהַתּוֹרָה לְגַמְרֵי, חַס וְשָׁלוֹם, מִשָּׁם נִמְשָׁכִין כָּל הַהֶזֵּקוֹת שֶׁל בְּחִינַת אֳנָסִין, שֶׁמִּתְגַּבְּרִין הַמַּזִּיקֵי עָלְמָא וְגוֹזְלִין מִמֶּנּוּ הַדָּבָר בְּאֹנֶס, בְּטַעֲנַת לִסְטִים אַתֶּם הַנַּ"ל. כִּי מֵאַחַר שֶׁאֵינוֹ עוֹסֵק בַּתּוֹרָה וְאֵינוֹ מַמְשִׁיךְ הָאֱמוּנָה בָּעוֹלָם, יֵשׁ לָהֶם כֹּחַ חַס וְשָׁלוֹם לוֹמַר לִסְטִים אַתֶּם וְכוּ' כַּנַּ"ל, וְעַל־כֵּן מִתְגַּבְּרִים וְנוֹטְלִין מִמֶּנּוּ הַדָּבָר בְּאֹנֶס, חַס וְשָׁלוֹם; אֲבָל כְּשֶׁעוֹסֵק בַּתּוֹרָה הוּא נִשְׁמָר מֵהֶם, כִּי שׁוּב אֵין לָהֶם כֹּחַ לוֹמַר לִסְטִים אַתֶּם כַּנַּ"ל. אֲבָל מֵחֲמַת שֶׁאִי אֶפְשָׁר לַעֲסֹק בַּתּוֹרָה תָּמִיד, וּבְהֶכְרֵחַ לְהִתְבַּטֵּל לִפְעָמִים, וַאֲזַי צְרִיכִין לְהַחֲיוֹת עַצְמוֹ גַּם אָז עַל־יְדֵי הַתּוֹרָה הַנֶּעְלֶמֶת בְּדֶרֶךְ־אֶרֶץ, דְּהַיְנוּ שֶׁצְּרִיכִין לְדַבֵּק מַחֲשַׁבְתּוֹ תָּמִיד בְּהַשֵּׁם יִתְבָּרַךְ וּבְהַתּוֹרָה, אֲפִלּוּ בְּעֵת עָסְקוֹ בְּמַשָּׂא־ וּמַתָּן וַעֲסָקִים וּמְלָאכוֹת, וְלֵידַע וּלְהַאֲמִין בְּכָל עֵת שֶׁכָּל דָּבָר שֶׁעוֹסְקִים בּוֹ, הַכֹּל בָּרָא הַשֵּׁם יִתְבָּרַךְ בִּרְצוֹנוֹ בַּעֲשָׂרָה מַאֲמָרוֹת, שֶׁבָּהֶם נֶעְלָמוֹת עֲשֶׂרֶת הַדִּבְּרוֹת שֶׁהֵם כָּל הַתּוֹרָה, וּלְהַחֲיוֹת אֶת עַצְמוֹ גַּם אָז בְּכֹחַ הַתּוֹרָה הַנֶּעְלֶמֶת בְּתוֹךְ דֶּרֶךְ־אֶרֶץ, וְהַכֹּל בְּכֹחַ הַצַּדִּיק הַגָּדוֹל כַּנַּ"ל. וּמִי שֶׁפּוֹגֵם בָּזֶה חַס וְשָׁלוֹם וְשׁוֹכֵחַ וּמַסִּיחַ דַּעְתּוֹ מֵהַתּוֹרָה וּמֵהַשֵּׁם יִתְבָּרַךְ בְּעֵת הָעֵסֶק בְּמַשָּׂא־וּמַתָּן, וְהוּא רָחוֹק אָז מֵהַתּוֹרָה לְגַמְרֵי - מִזֶּה בָּאִין חַס וְשָׁלוֹם הַהֶזֵּקוֹת שֶׁל גְּנֵבָה וַאֲבֵדָה, שֶׁהֵם בָּאִים רַק עַל־יְדֵי הֶסַּח הַדַּעַת, וְזֶה נִמְשָׁךְ מֵחֲמַת שֶׁפָּגַם וְהִסִּיחַ דַּעְתּוֹ לְגַמְרֵי מֵהַתּוֹרָה הַקְּדוֹשָׁה בְּעֵת הָעֵסֶק בְּמַשָּׂא־וּמַתָּן. אֲבָל מִי שֶׁמְּקֻשָּׁר לְהַצַּדִּיק־הָאֱמֶת, וַאֲפִלּוּ בְּעֵת שֶׁבָּטֵל מֵהַתּוֹרָה וְעוֹסֵק בְּמַשָּׂא־וּמַתָּן הוּא מְקֻשָּׁר גַּם־כֵּן אֶל הַתּוֹרָה, וּמְחַיֶּה אֶת עַצְמוֹ עִם הַתּוֹרָה הַנֶּעְלֶמֶת, וּבְכֹחַ הַצַּדִּיק הַגָּדוֹל הָעוֹסֵק לְגַלּוֹת וּלְהַמְשִׁיךְ זֶה הַחֶסֶד חִנָּם וְהַתּוֹרָה הַנֶּעְלֶמֶת, עַל־יְדֵי־זֶה הוּא נִשְׁמָר גַּם מִגְּנֵבָה וַאֲבֵדָה שֶׁבָּא עַל־יְדֵי הֶסַּח הַדָּעַת. וְזֶה בְּחִינַת מַה שֶּׁהַשּׁוֹמֵר שָׂכָר חַיָּב בִּגְנֵבָה וַאֲבֵדָה וּפָטוּר מֵאֳנָסִין, וְכַמְבֹאָר בִּפְנִים (שם
